     for(let x=0;x<W;x++){
       const i=y*W+x;
       barrier[i]=luma[i]<220||(x>0&&luma[i-1]<220)||(x<W-1&&luma[i+1]<220)||(y>0&&luma[i-W]<220)||(y<H-1&&luma[i+W]<220)?1:0;
     }
