     const gx=index%W,gy=(index/W)|0,x=gx-region.minX,y=gy-region.minY,k=(y*width+x)*4,u=x/Math.max(1,width-1),v=y/Math.max(1,height-1);
     let t=Math.max(0,Math.min(1,.55-.55*v+.30*u)),a=t<.5?stops[0]:stops[1],b=t<.5?stops[1]:stops[2],m=t<.5?t*2:(t-.5)*2;
