       t=Math.max(0,Math.min(1,t));const a=t<.5?stops[0]:stops[1],b=t<.5?stops[1]:stops[2],m=t<.5?t*2:(t-.5)*2;
       for(let c=0;c<3;c++)data[k+c]=a[c]+(b[c]-a[c])*m;
